const pedido = String((($input.first().json.body) || {}).mes || '').trim();
const mes = /^\d{4}-(0[1-9]|1[0-2])$/.test(pedido) ? pedido : $now.toFormat('yyyy-MM');
return [{ json: { mes, manual: Boolean($input.first().json.headers) } }];

const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];

function mod10(numero) {
  let soma = 0;
  let peso = 2;
  for (let i = numero.length - 1; i >= 0; i--) {
    let parcial = Number(numero[i]) * peso;
    if (parcial > 9) parcial = Math.floor(parcial / 10) + (parcial % 10);
    soma += parcial;
    peso = peso === 2 ? 1 : 2;
  }
  return (10 - (soma % 10)) % 10;
}

function mod11(numero, arrecadacao) {
  let soma = 0;
  let peso = 2;
  for (let i = numero.length - 1; i >= 0; i--) {
    soma += Number(numero[i]) * peso;
    peso = peso === 9 ? 2 : peso + 1;
  }
  const resto = soma % 11;
  if (arrecadacao) return resto === 0 || resto === 1 ? 0 : 11 - resto;
  const dv = 11 - resto;
  return dv === 0 || dv === 10 || dv === 11 ? 1 : dv;
}

function vencimentoPorFator(fator, referencia) {
  if (!fator) return '';
  const dia = 24 * 60 * 60 * 1000;
  const candidatos = [Date.UTC(1997, 9, 7) + fator * dia];
  if (fator >= 1000) candidatos.push(Date.UTC(2025, 1, 22) + (fator - 1000) * dia);
  const alvo = referencia ? Date.parse(referencia) : Date.now();
  candidatos.sort((a, b) => Math.abs(a - alvo) - Math.abs(b - alvo));
  return new Date(candidatos[0]).toISOString().slice(0, 10);
}

function conferirLinha(linha, referencia) {
  const d = String(linha || '').replace(/\D/g, '');
  if (!d) return { ok: false, motivo: '' };
  if (d.length === 47) {
    const campos = [[0, 9], [10, 20], [21, 31]];
    for (const [ini, fim] of campos) {
      if (mod10(d.slice(ini, fim)) !== Number(d[fim])) return { ok: false, motivo: 'dígito de um campo da linha digitável não confere' };
    }
    const barras = d.slice(0, 4) + d[32] + d.slice(33, 47) + d.slice(4, 9) + d.slice(10, 20) + d.slice(21, 31);
    if (mod11(barras.slice(0, 4) + barras.slice(5), false) !== Number(barras[4])) return { ok: false, motivo: 'dígito geral do boleto não confere' };
    return { ok: true, digitos: d, barras, valor: Number(d.slice(37, 47)) / 100, vencimento: vencimentoPorFator(Number(d.slice(33, 37)), referencia) };
  }
  if (d.length === 48 && d[0] === '8') {
    const id = d[2];
    const blocos = [0, 12, 24, 36].map((i) => d.slice(i, i + 12));
    for (const bloco of blocos) {
      const dv = id === '6' || id === '7' ? mod10(bloco.slice(0, 11)) : mod11(bloco.slice(0, 11), true);
      if (dv !== Number(bloco[11])) return { ok: false, motivo: 'dígito de um bloco da conta não confere' };
    }
    const barras = blocos.map((b) => b.slice(0, 11)).join('');
    const valor = id === '6' || id === '8' ? Number(barras.slice(4, 15)) / 100 : null;
    return { ok: true, digitos: d, barras, valor, vencimento: '' };
  }
  return { ok: false, motivo: `linha digitável com ${d.length} dígitos (esperado 47 ou 48)` };
}

function crc16(texto) {
  let crc = 0xffff;
  for (const byte of Buffer.from(texto, 'utf8')) {
    crc ^= byte << 8;
    for (let i = 0; i < 8; i++) crc = crc & 0x8000 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}

function conferirPix(pix) {
  const p = String(pix || '').trim();
  if (!p) return { ok: false, motivo: '' };
  const m = p.match(/^(.*6304)([0-9A-Fa-f]{4})$/s);
  if (!p.startsWith('000201') || !m) return { ok: false, motivo: 'Pix copia e cola fora do formato' };
  if (crc16(m[1]) !== m[2].toUpperCase()) return { ok: false, motivo: 'CRC do Pix não confere' };
  return { ok: true, codigo: p };
}

function reais(valor) {
  if (valor === null || valor === undefined || Number.isNaN(Number(valor))) return 'R$ ?';
  return 'R$ ' + Number(valor).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

function brData(iso) {
  const [a, m, d] = String(iso).split('-');
  return d && m && a ? `${d}/${m}/${a}` : iso;
}

function titulo(mes) {
  const [a, m] = mes.split('-');
  return `# ${a}-${m}`;
}

function barrasItf(codigo) {
  const padroes = ['00110', '10001', '01001', '11000', '00101', '10100', '01100', '00011', '10010', '01010'];
  const fino = 1;
  const largo = 3;
  const margem = 10;
  const barras = [];
  let x = margem;
  const desenhar = (largura, barra) => {
    if (barra) barras.push([x, largura]);
    x += largura;
  };
  [true, false, true, false].forEach((barra) => desenhar(fino, barra));
  for (let i = 0; i < codigo.length; i += 2) {
    const a = padroes[Number(codigo[i])];
    const b = padroes[Number(codigo[i + 1])];
    for (let j = 0; j < 5; j++) {
      desenhar(a[j] === '1' ? largo : fino, true);
      desenhar(b[j] === '1' ? largo : fino, false);
    }
  }
  desenhar(largo, true);
  desenhar(fino, false);
  desenhar(fino, true);
  return { barras, largura: x + margem };
}

function codigoDeBarrasSvg(codigo) {
  const altura = 50;
  const { barras, largura } = barrasItf(codigo);
  const retangulos = barras.map(([x, w]) => `<rect x="${x}" y="0" width="${w}" height="${altura}"/>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${largura} ${altura}" width="${largura * 2}" height="${altura * 2}" shape-rendering="crispEdges"><rect width="${largura}" height="${altura}" fill="#fff"/><g fill="#000">${retangulos}</g></svg>`;
}

function nomeImagem(prefixo, codigo) {
  return `${prefixo}-${require('crypto').createHash('sha1').update(codigo).digest('hex').slice(0, 10)}.svg`;
}

function nomeDoMes(mes) {
  const [a, m] = mes.split('-');
  return `${MESES[Number(m) - 1]} de ${a}`;
}

const cfg = $('⚙️ Configuração').first().json.config;
const { mes } = $('🗓️ Mês').first().json;
const texto = typeof $input.first().json.conteudo === 'string' ? $input.first().json.conteudo : '';
const para = String(cfg.destinatarios || '').split(/[,;\s]+/).map((s) => s.trim()).filter((s) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s));
const html = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const contas = [];
for (const bloco of texto.split(/^-{3,}\s*$/m)) {
  const campo = (nome) => ((bloco.match(new RegExp(`^\\*\\*${nome}\\*\\*: *(.*)$`, 'm')) || [])[1] || '').trim();
  const conta = campo('Conta');
  if (!conta) continue;
  const codigo = (nome) => campo(nome).replace(/^`|`$/g, '').trim();
  contas.push({
    conta, valor: campo('Valor'), titular: campo('Titular'), vencimento: campo('Vencimento'),
    pago: /^- \[[xX]\] \*\*Pago\*\*/m.test(bloco), pix: codigo('Pix copia e cola'), boleto: codigo('Boleto'),
    observacoes: campo('Observações'),
  });
}
const nomeMes = nomeDoMes(mes);
if (!para.length || !contas.length) {
  return [{ json: { enviar: false, mes, nomeMes, total: contas.length, mensagem: !para.length
    ? `⚠️ E-mail das contas de ${nomeMes} não enviado: preencha os destinatários no ⚙️ Configuração do módulo Contas: e-mail mensal`
    : `📭 Nenhuma conta em ${nomeMes}: e-mail não enviado` } }];
}
const QRCode = require('qrcode');
const { PNG } = require('pngjs');
function barrasPng(barras) {
  const { barras: lista, largura } = barrasItf(barras);
  const escala = 2;
  const altura = 100;
  const png = new PNG({ width: largura * escala, height: altura });
  png.data.fill(255);
  for (const [x, w] of lista) {
    for (let px = x * escala; px < (x + w) * escala; px++) {
      for (let y = 0; y < altura; y++) {
        const k = (y * png.width + px) * 4;
        png.data[k] = png.data[k + 1] = png.data[k + 2] = 0;
      }
    }
  }
  return PNG.sync.write(png);
}
const anexos = [];
const partesHtml = [];
const partesTexto = [];
for (const [i, c] of contas.entries()) {
  const linhasHtml = [`<p style="margin:0 0 6px;font-size:17px"><b>${html(c.conta)}</b> · ${html(c.valor)}${c.pago ? ' · ✅ paga' : ''}</p>`];
  const linhasTexto = [`${c.conta} · ${c.valor}${c.pago ? ' · paga' : ''}`];
  if (c.titular) { linhasHtml.push(`<p style="margin:0">Titular: ${html(c.titular)}</p>`); linhasTexto.push(`Titular: ${c.titular}`); }
  if (c.vencimento) { linhasHtml.push(`<p style="margin:0">Vencimento: <b>${html(c.vencimento)}</b></p>`); linhasTexto.push(`Vencimento: ${c.vencimento}`); }
  if (!c.pago) {
    const pix = conferirPix(c.pix);
    const linha = conferirLinha(c.boleto);
    if (c.pix) {
      linhasHtml.push(`<p style="margin:10px 0 4px">Pix copia e cola:</p><p style="margin:0;font-family:monospace;font-size:12px;word-break:break-all">${html(c.pix)}</p>`);
      linhasTexto.push(`Pix copia e cola: ${c.pix}`);
      if (pix.ok) {
        const cid = `pix-${i}`;
        anexos.push({ nome: `${cid}.png`, tipo: 'image/png', cid, base64: (await QRCode.toBuffer(pix.codigo, { type: 'png', errorCorrectionLevel: 'M', margin: 2, width: 300 })).toString('base64') });
        linhasHtml.push(`<p style="margin:8px 0 0"><img src="cid:${cid}" width="220" height="220" alt="QR Code do Pix"></p>`);
      }
    } else if (c.boleto) {
      linhasHtml.push(`<p style="margin:10px 0 4px">Boleto:</p><p style="margin:0;font-family:monospace;font-size:13px;word-break:break-all">${html(c.boleto)}</p>`);
      linhasTexto.push(`Boleto: ${c.boleto}`);
      if (linha.ok) {
        const cid = `boleto-${i}`;
        const png = barrasPng(linha.barras);
        anexos.push({ nome: `${cid}.png`, tipo: 'image/png', cid, base64: png.toString('base64') });
        linhasHtml.push(`<p style="margin:8px 0 0"><img src="cid:${cid}" width="${barrasItf(linha.barras).largura}" height="50" alt="Código de barras do boleto"></p>`);
      }
    }
  }
  if (c.observacoes) { linhasHtml.push(`<p style="margin:8px 0 0;color:#666">${html(c.observacoes)}</p>`); linhasTexto.push(`Observações: ${c.observacoes}`); }
  partesHtml.push(`<div style="border:1px solid #ddd;border-radius:8px;padding:14px;margin:0 0 14px">${linhasHtml.join('')}</div>`);
  partesTexto.push(linhasTexto.join('\n'));
}
const pendentes = contas.filter((c) => !c.pago).length;
const assunto = `Contas a pagar · ${nomeMes}`;
const resumo = `${contas.length} conta(s), ${pendentes} a pagar`;
const corpoHtml = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#222;max-width:640px"><h2 style="margin:0 0 4px">${html(assunto)}</h2><p style="margin:0 0 16px;color:#666">${html(resumo)}</p>${partesHtml.join('')}</div>`;
const corpoTexto = `${assunto}\n${resumo}\n\n${partesTexto.join('\n\n---\n\n')}\n`;
return [{ json: { enviar: true, mes, nomeMes, total: contas.length, pendentes, pedido: { para, assunto, texto: corpoTexto, html: corpoHtml, anexos } } }];

const montado = $('✉️ Montar e-mail').first().json;
if (!montado.enviar) return [{ json: { mensagem: montado.mensagem } }];
const r = $input.first().json || {};
const enviados = Array.isArray(r.enviados) ? r.enviados : [];
const erros = Array.isArray(r.erros) ? r.erros : [];
const linhas = [];
if (enviados.length) linhas.push(`📧 E-mail das contas de ${montado.nomeMes} (${montado.total} conta(s), ${montado.pendentes} a pagar) enviado para ${enviados.join(', ')}`);
for (const e of erros) linhas.push(`⚠️ não enviado para ${e.para}: ${e.erro}`);
if (!enviados.length && !erros.length) linhas.push(`⚠️ E-mail das contas de ${montado.nomeMes} não enviado: ${r.erro || (r.error && (r.error.message || JSON.stringify(r.error))) || 'resposta inesperada do envio'}`);
return [{ json: { mensagem: linhas.join('\n').slice(0, 1900) } }];
